// Le fil de 4e suit la progression 2026–2027 et les codes du livret.
// Chaque ligne relie une compétence à un entraînement et aux deux sujets blancs.
function chapter4(id, code, title, links, example, recap, rows, track) {
  const item = ([prompt, answer, explain, written = false], skill) => ({prompt, answer, explain, written, skill});
  return {
    id, code, title, links, example, recap, track,
    skills: rows.map(([skill]) => skill),
    practice: rows.map((row, index) => item(row[1], index)),
    tests: [2, 3].map(version => rows.map((row, index) => item(row[version], index))),
  };
}

