const quatrePythagore = chapter4("pythagore-direct", "Ch. 3 · G02", "Théorème de Pythagore", ["pythagore", "racines4"],
  "Si ABC est rectangle en B, AC est l’hypoténuse. Avec AB = 5 cm et BC = 7 cm, AC² = 25 + 49 = 74 cm², donc AC = √74 cm ≈ 8,6 cm.",
  "Dans un triangle rectangle, l’aire du carré construit sur l’hypoténuse égale la somme des aires des deux autres carrés. Nomme l’angle droit et l’hypoténuse. Écris la relation avant de calculer. Garde la valeur exacte avant d’arrondir.",
  [
    ["Identifier l’hypoténuse et écrire le théorème avec les lettres",
      ["RST est rectangle en T. Nomme l’hypoténuse et écris l’égalité de Pythagore.", "RS ; RS² = RT² + ST².", "RS est le côté opposé à l’angle droit T. Le carré de sa longueur est seul d’un côté de l’égalité.", true],
      ["Un triangle ABC a un angle droit en C. Une élève écrit AC² = AB² + BC². Corrige et justifie.", "AB² = AC² + BC².", "AB est opposé à C, donc c’est l’hypoténuse.", true],
      ["Un triangle MNP a un angle droit en M. Sur un croquis de ton choix, place les trois carrés du théorème et indique la relation entre leurs aires.", "Aire du carré sur NP = aire sur MN + aire sur MP.", "L’orientation du croquis ne change pas l’hypoténuse NP. Les carrés sont construits sur chacun des côtés.", true]],
    ["Calculer une longueur, donner une valeur exacte et un arrondi",
      ["Dans un triangle rectangle, l’hypoténuse mesure 13 cm et un autre côté 5 cm. Calcule le troisième côté en cm.", "12", "Le carré de la longueur cherchée est 13² − 5² = 144. On prend la racine carrée positive."],
      ["Le triangle EFG est rectangle en F. EF = 7 cm et FG = 8 cm. Donne EG exactement puis au dixième.", "√113 cm, environ 10,6 cm.", "EG² = 7² + 8² = 113 cm². On prend la racine carrée avant d’arrondir.", true],
      ["Le triangle JKL est rectangle en K. JL = 11 m et KL = 6 m. Donne JK exactement puis au dixième.", "√85 m, environ 9,2 m.", "JK² = 11² − 6² = 85 m². La valeur positive est √85 m.", true]],
    ["Mobiliser Pythagore et la proportionnalité dans un problème",
      ["Une maquette rectangulaire mesure 9 cm sur 12 cm. Sur le terrain, 1 cm représente 2 m. Quelle est la diagonale sur le terrain, en m ?", "30", "La diagonale du modèle est √(81 + 144) = 15 cm. On multiplie par 2."],
      ["Une carte à l’échelle 1 : 500 montre un jardin rectangulaire de 3 cm sur 8 cm. On dispose de 45 m de câble. Est-ce suffisant pour relier deux coins opposés du terrain ?", "Oui, la diagonale mesure environ 42,7 m.", "Sur la carte la diagonale vaut √73 cm. À l’échelle donnée, 1 cm représente 5 m, donc la diagonale réelle vaut 5√73 m.", true],
      ["Un plan à l’échelle 1 : 200 donne un rectangle de 6 cm sur 8 cm. Un câble va d’un coin à son opposé. On ajoute 1,50 m de marge. Combien de mètres de câble faut-il ?", "21,5", "La diagonale du plan vaut 10 cm. En réalité elle vaut 20 m. On ajoute la marge."]],
  ]);

